import { z } from 'zod';

/**
 * The Haunt Kit tour definition format. A tour is plain data (JSON or a
 * TypeScript object) so it can be written by hand, generated by an editor, or
 * carried inside a share link.
 */

const latLng = z.object({
  lat: z.number().min(-90).max(90),
  lng: z.number().min(-180).max(180),
});

const source = z.object({
  title: z.string().min(1),
  publisher: z.string().min(1),
  url: z.url(),
  /** ISO date the source was last checked. */
  accessed: z.iso.date().optional(),
});

const challenge = z.object({
  /** The question asked once the walker reaches the stop. */
  question: z.string().min(1),
  /** Accepted answers: plain text, or "sha256:<salt>:<base64url digest>" so a shared hunt does not leak them. */
  answers: z.array(z.string().min(1)).min(1),
  /** Optional nudge shown on request. */
  hint: z.string().optional(),
});

export const stopSchema = z.object({
  id: z.string().regex(/^[a-z0-9][a-z0-9-]*$/, 'ids are lowercase letters, digits and dashes'),
  name: z.string().min(1),
  position: latLng,
  /** Trigger radius in meters. GPS is rarely better than 5 m, so 10 m is the floor. */
  radius: z.number().min(10).max(500),
  /** What the walker reads (one string per paragraph) once the stop unlocks. */
  story: z.array(z.string().min(1)).min(1),
  /** A short teaser shown before arrival, so walkers know what to look for. */
  clue: z.string().optional(),
  /** Optional narration file (relative URL). Without one, the Narrator reads the story aloud. */
  audio: z.string().optional(),
  /** legend: a published local legend; history: documented fact; fiction: invented for this tour. */
  kind: z.enum(['legend', 'history', 'fiction', 'clue']).default('clue'),
  /** Public sources for anything that is not fiction. */
  sources: z.array(source).default([]),
  /** Shown before arrival: how to visit respectfully (for example "view from the sidewalk"). */
  etiquette: z.string().optional(),
  challenge: challenge.optional(),
  /** Stop ids that must be finished before this one unlocks. */
  requires: z.array(z.string()).default([]),
  /** A finale unlocks only after every other stop is finished. */
  finale: z.boolean().default(false),
});

const mapFeature = z.object({
  kind: z.enum(['river', 'street', 'park', 'landmark']),
  name: z.string(),
  path: z.array(latLng).min(1),
  /** Where to print the name. Defaults to the middle point of the path. */
  labelAt: latLng.optional(),
});

export const tourSchema = z
  .object({
    id: z.string().regex(/^[a-z0-9][a-z0-9-]*$/),
    title: z.string().min(1),
    subtitle: z.string().optional(),
    /** free: any order; sequential: stop n+1 waits for stop n. Per-stop `requires` and `finale` apply on top. */
    ordering: z.enum(['free', 'sequential']).default('free'),
    stops: z.array(stopSchema).min(1),
    /** Walking route used to draw the path and to drive the simulated walk. Defaults to the stops in order. */
    route: z.array(latLng).optional(),
    /** Stylized map decoration (rivers, streets, parks), drawn in SVG. */
    mapFeatures: z.array(mapFeature).default([]),
    credits: z.string().optional(),
  })
  .superRefine((tour, ctx) => {
    const ids = new Set<string>();
    tour.stops.forEach((stop, i) => {
      if (ids.has(stop.id)) ctx.addIssue({ code: 'custom', path: ['stops', i, 'id'], message: `duplicate stop id "${stop.id}"` });
      ids.add(stop.id);
    });
    tour.stops.forEach((stop, i) => {
      for (const req of stop.requires) {
        if (!ids.has(req)) ctx.addIssue({ code: 'custom', path: ['stops', i, 'requires'], message: `unknown stop "${req}"` });
        if (req === stop.id) ctx.addIssue({ code: 'custom', path: ['stops', i, 'requires'], message: 'a stop cannot require itself' });
      }
      if ((stop.kind === 'legend' || stop.kind === 'history') && stop.sources.length === 0) {
        ctx.addIssue({ code: 'custom', path: ['stops', i, 'sources'], message: `${stop.kind} stops must cite a public source` });
      }
    });
    if (tour.stops.filter((s) => s.finale).length > 1) {
      ctx.addIssue({ code: 'custom', path: ['stops'], message: 'a tour has at most one finale' });
    }
    if (hasCycle(tour.stops)) ctx.addIssue({ code: 'custom', path: ['stops'], message: '`requires` forms a cycle, so some stops can never unlock' });
  });

export type TourInput = z.input<typeof tourSchema>;
export type Tour = z.output<typeof tourSchema>;
export type Stop = z.output<typeof stopSchema>;
export type StopKind = Stop['kind'];
export type Source = z.output<typeof source>;

export class TourValidationError extends Error {
  constructor(readonly issues: string[]) {
    super(`Invalid tour:\n- ${issues.join('\n- ')}`);
    this.name = 'TourValidationError';
  }
}

/** Validates and normalizes a tour, filling defaults. Throws TourValidationError with readable issues. */
export function parseTour(input: unknown): Tour {
  const result = tourSchema.safeParse(input);
  if (!result.success) {
    throw new TourValidationError(
      result.error.issues.map((issue) => `${issue.path.join('.') || '(tour)'}: ${issue.message}`),
    );
  }
  return result.data;
}

/** Like parseTour but returns the issues instead of throwing. */
export function validateTour(input: unknown): { ok: true; tour: Tour } | { ok: false; issues: string[] } {
  try {
    return { ok: true, tour: parseTour(input) };
  } catch (err) {
    if (err instanceof TourValidationError) return { ok: false, issues: err.issues };
    throw err;
  }
}

/** Typed helper for authoring tours in TypeScript. Validates at module load. */
export function defineTour(input: TourInput): Tour {
  return parseTour(input);
}

/** The route a walker follows: the explicit route, or the stops in listed order. */
export function tourRoute(tour: Tour) {
  return tour.route && tour.route.length > 1 ? tour.route : tour.stops.map((s) => s.position);
}

function hasCycle(stops: { id: string; requires: string[] }[]): boolean {
  const graph = new Map(stops.map((s) => [s.id, s.requires]));
  const state = new Map<string, 'visiting' | 'done'>();
  const visit = (id: string): boolean => {
    const mark = state.get(id);
    if (mark === 'visiting') return true;
    if (mark === 'done') return false;
    state.set(id, 'visiting');
    for (const next of graph.get(id) ?? []) if (graph.has(next) && visit(next)) return true;
    state.set(id, 'done');
    return false;
  };
  return stops.some((s) => visit(s.id));
}
